pub fn decode(alloc: std.mem.Allocator, data: []const u8) DecodeError!RawStatelessInput {
    return decodeRaw(alloc, data) catch |err| switch (err) {
        error.InvalidSsz => {
            if (!hasExactErePrefix(data)) return error.InvalidSsz;
            return decodeRaw(alloc, data[4..]);
        },
        else => return err,
    };
}

fn hasExactErePrefix(data: []const u8) bool {
    if (data.len < 4 or data.len - 4 > std.math.maxInt(u32)) return false;
    const declared = std.mem.readInt(u32, data[0..4], .little);
    return declared == data.len - 4;
}

pub inline fn readInt(comptime T: type, buffer: *const [@divExact(@typeInfo(T).int.bits, 8)]u8, endian: Endian) T {
    const value: T = @bitCast(buffer.*);
    return if (endian == native_endian) value else @byteSwap(value);
}

pub fn decodeRaw(alloc: std.mem.Allocator, data: []const u8) DecodeError!RawStatelessInput {
    try requireU32Length(data);
    if (data.len < schema_id.len or !std.mem.eql(u8, data[0..schema_id.len], &schema_id)) {
        return error.InvalidSsz;
    }

    const body = data[schema_id.len..];
    if (body.len < TOP_FIXED_SIZE) return error.InvalidSsz;
    const offsets = [_]usize{
        try readOffset(body, 0),
        try readOffset(body, 4),
        try readOffset(body, 8),
        try readOffset(body, 12),
    };
    try requireCanonicalOffsets(body, TOP_FIXED_SIZE, &offsets);

    var result: RawStatelessInput = undefined;
    result.new_payload_request = try decodeNewPayloadRequest(alloc, body[offsets[0]..offsets[1]]);
    errdefer result.new_payload_request.deinit(alloc);
    result.witness = try decodeExecutionWitness(alloc, body[offsets[1]..offsets[2]]);
    errdefer result.witness.deinit(alloc);
    result.chain_config = try decodeChainConfig(body[offsets[2]..offsets[3]]);
    result.public_keys = try decodePublicKeys(alloc, body[offsets[3]..]);
    errdefer alloc.free(result.public_keys);
    return result;
}

fn requireU32Length(data: []const u8) DecodeError!void {
    if (data.len > std.math.maxInt(u32)) return error.InvalidSsz;
}

pub fn eql(comptime T: type, a: []const T, b: []const T) bool {
    if (!@inComptime() and @sizeOf(T) != 0 and std.meta.hasUniqueRepresentation(T) and
        use_vectors_for_comparison)
    {
        return eqlBytes(sliceAsBytes(a), sliceAsBytes(b));
    }

    if (a.len != b.len) return false;
    if (a.len == 0 or a.ptr == b.ptr) return true;

    for (a, b) |a_elem, b_elem| {
        if (a_elem != b_elem) return false;
    }
    return true;
}

fn eqlBytes(a: []const u8, b: []const u8) bool {
    comptime assert(use_vectors_for_comparison);

    if (a.len != b.len) return false;
    if (a.len == 0 or a.ptr == b.ptr) return true;

    if (a.len <= 16) {
        if (a.len < 4) {
            const x = (a[0] ^ b[0]) | (a[a.len - 1] ^ b[a.len - 1]) | (a[a.len / 2] ^ b[a.len / 2]);
            return x == 0;
        }
        var x: u32 = 0;
        for ([_]usize{ 0, a.len - 4, (a.len / 8) * 4, a.len - 4 - ((a.len / 8) * 4) }) |n| {
            x |= @as(u32, @bitCast(a[n..][0..4].*)) ^ @as(u32, @bitCast(b[n..][0..4].*));
        }
        return x == 0;
    }

    // Figure out the fastest way to scan through the input in chunks.
    // Uses vectors when supported and falls back to usize/words when not.
    const Scan = if (std.simd.suggestVectorLength(u8)) |vec_size|
        struct {
            pub const size = vec_size;
            pub const Chunk = @Vector(size, u8);
            pub inline fn isNotEqual(chunk_a: Chunk, chunk_b: Chunk) bool {
                return @reduce(.Or, chunk_a != chunk_b);
            }
        }
    else
        struct {
            pub const size = @sizeOf(usize);
            pub const Chunk = usize;
            pub inline fn isNotEqual(chunk_a: Chunk, chunk_b: Chunk) bool {
                return chunk_a != chunk_b;
            }
        };

    inline for (1..6) |s| {
        const n = 16 << s;
        if (n <= Scan.size and a.len <= n) {
            const V = @Vector(n / 2, u8);
            var x = @as(V, a[0 .. n / 2].*) ^ @as(V, b[0 .. n / 2].*);
            x |= @as(V, a[a.len - n / 2 ..][0 .. n / 2].*) ^ @as(V, b[a.len - n / 2 ..][0 .. n / 2].*);
            const zero: V = @splat(0);
            return !@reduce(.Or, x != zero);
        }
    }
    // Compare inputs in chunks at a time (excluding the last chunk).
    for (0..(a.len - 1) / Scan.size) |i| {
        const a_chunk: Scan.Chunk = @bitCast(a[i * Scan.size ..][0..Scan.size].*);
        const b_chunk: Scan.Chunk = @bitCast(b[i * Scan.size ..][0..Scan.size].*);
        if (Scan.isNotEqual(a_chunk, b_chunk)) return false;
    }

    // Compare the last chunk using an overlapping read (similar to the previous size strategies).
    const last_a_chunk: Scan.Chunk = @bitCast(a[a.len - Scan.size ..][0..Scan.size].*);
    const last_b_chunk: Scan.Chunk = @bitCast(b[a.len - Scan.size ..][0..Scan.size].*);
    return !Scan.isNotEqual(last_a_chunk, last_b_chunk);
}

